package com.bocsoft.sqleditor.metadata;
import com.bocsoft.sqleditor.auth.CurrentAuth;import com.bocsoft.sqleditor.datasource.api.CursorPage;import com.bocsoft.sqleditor.metadata.api.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/data-sources/{id}") public class MetadataController {private final MysqlMetadataService service;public MetadataController(MysqlMetadataService service){this.service=service;}
 @GetMapping("/databases") public CursorPage<DatabaseItem>databases(@PathVariable String id,@RequestParam(defaultValue="")String keyword,@RequestParam(defaultValue="100")int pageSize,@RequestParam(required=false)String pageToken,@RequestParam(defaultValue="false")boolean includeSystem){return service.databases(CurrentAuth.get(),id,keyword,pageSize,pageToken,includeSystem);}
 @GetMapping("/tables") public CursorPage<TableItem>tables(@PathVariable String id,@RequestParam String database,@RequestParam(defaultValue="")String keyword,@RequestParam(defaultValue="TABLE,VIEW")String types,@RequestParam(defaultValue="200")int pageSize,@RequestParam(required=false)String pageToken){return service.tables(CurrentAuth.get(),id,database,keyword,types,pageSize,pageToken);}
 @GetMapping("/table-detail") public TableDetailResponse detail(@PathVariable String id,@RequestParam String database,@RequestParam String table){return service.detail(CurrentAuth.get(),id,database,table);}}
